//! Schema IR v1: model description, relaxed binding and typed coercion.
//!
//! The IR is generated by the calling layer from its model types and consumed by the
//! engine. It is the compatibility contract between both sides and is versioned apart from
//! the package (see ADR 0004).
//!
//! The engine is language neutral: it knows nothing about the types of any particular
//! host language. Rich types (`enum`, `path`, `decimal`, `uuid`, `secret`) are validated
//! here and constructed by the caller.

use std::collections::BTreeMap;

use serde::Deserialize;

use crate::error::{Error, Result};
use crate::value::Span;

mod bind;
mod coerce;
mod unknown;

pub use bind::bind_env;
pub use coerce::{Coerced, coerce};
pub use unknown::{UnknownKey, unknown_keys};

/// Version of the IR understood by this engine.
pub const IR_VERSION: &str = "keydex.schema/v1";

/// Model schema.
#[derive(Debug, Clone, Deserialize)]
pub struct Schema {
    /// Contract version (`keydex.schema/v1`).
    pub ir: String,
    /// Root node, normally a `struct`.
    pub root: Field,
}

impl Schema {
    /// Parses and validates a JSON IR.
    pub fn from_json(text: &str) -> Result<Self> {
        let schema: Self = serde_json::from_str(text).map_err(|err| Error::Parse {
            file: String::from("<schema>"),
            message: err.to_string(),
        })?;
        if schema.ir != IR_VERSION {
            return Err(Error::UnsupportedSchema {
                found: schema.ir,
                expected: IR_VERSION.to_string(),
            });
        }
        schema.validate()?;
        Ok(schema)
    }

    /// Rejects an IR that is structurally wrong, instead of failing at load time.
    pub fn validate(&self) -> Result<()> {
        if !matches!(self.root.kind, FieldType::Struct { .. }) {
            return Err(Error::InvalidSchema {
                message: String::from("the root field must be a struct"),
            });
        }
        walk(&self.root, "root")
    }
}

fn walk(field: &Field, path: &str) -> Result<()> {
    match &field.kind {
        FieldType::Struct { fields } => {
            for (name, child) in fields {
                walk(child, &format!("{path}.{name}"))?;
            }
        }
        FieldType::List { items } => walk(items, &format!("{path}[]"))?,
        FieldType::Map { values } => walk(values, &format!("{path}.*"))?,
        FieldType::Optional { inner } | FieldType::Secret { inner } => {
            walk(inner, &format!("{path}?"))?;
        }
        FieldType::Enum { variants } if variants.is_empty() => {
            return Err(Error::InvalidSchema {
                message: format!("{path}: enum without variants"),
            });
        }
        _ => {}
    }
    Ok(())
}

/// Schema node.
#[derive(Debug, Clone, Deserialize)]
pub struct Field {
    /// The type itself.
    #[serde(flatten)]
    pub kind: FieldType,
    /// `true` when the value must exist.
    #[serde(default)]
    pub required: bool,
    /// `true` when the model declares a default for this field.
    #[serde(default)]
    pub has_default: bool,
}

/// Type of a schema node.
#[derive(Debug, Clone, Deserialize)]
#[serde(tag = "type", rename_all = "snake_case")]
pub enum FieldType {
    /// Text.
    Str,
    /// Integer.
    Int,
    /// Floating point.
    Float,
    /// Boolean.
    Bool,
    /// Any scalar, passed through without conversion.
    Any,
    /// Filesystem path.
    Path,
    /// Exact decimal number, carried as text.
    Decimal,
    /// UUID.
    Uuid,
    /// One of a closed set of string values.
    Enum {
        /// Accepted values, compared case-insensitively.
        variants: Vec<String>,
    },
    /// Sensitive value; the caller wraps it.
    Secret {
        /// Inner type.
        inner: Box<Field>,
    },
    /// Absent or explicit `null`.
    Optional {
        /// Inner type.
        inner: Box<Field>,
    },
    /// Sequence, replaced whole by higher-priority sources.
    List {
        /// Element type.
        items: Box<Field>,
    },
    /// Free-form string-keyed map.
    Map {
        /// Value type.
        values: Box<Field>,
    },
    /// Object, merged key by key.
    Struct {
        /// Fields by name.
        fields: BTreeMap<String, Field>,
    },
}

/// Validation error for a specific value.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ValidationError {
    /// Key path: `db.port`, `servers[0].host`.
    pub path: String,
    /// What is wrong.
    pub message: String,
    /// Position in the document, when known.
    pub span: Option<Span>,
}

impl std::fmt::Display for ValidationError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match &self.span {
            Some(span) => write!(
                f,
                "{}:{}: {}: {}",
                span.file, span.line, self.path, self.message
            ),
            None => write!(f, "{}: {}", self.path, self.message),
        }
    }
}
